                    return each * 3, "{}符{}Han{}点∀".format(fu, han, each)
                else:
                    dscore = ((base_score * 2 - 1) // 100 + 1) * 100
                    xscore = ((base_score - 1) // 100 + 1) * 100
                    return dscore + 2 * xscore, "{}符{}Han{}-{}点".format(fu, han, xscore, dscore)
