        else:
            return 0.01

    elif ind1[0] == 3 and ind2[0] == 3:
        if ind1[1] <= ind2[1]:
            # priority for boundaries more at the bottom (higher in y) as it is a right border
            if angle1 > 0:
                # if angle is bigger than zero, we give priority to more left boundaries
                if ind2[2] <= ind1[2]:
