def bin_search_range(array, hi, lo, min_r, max_r):    
    count = 0
    while True:
        mid = math.ceil((hi + lo) / 2)
        if lo >= hi:
            return count
        count += 1
        if min_r <= array[mid] <= max_r:
            mid1 = mid
            while True:
                # going backwards
                if mid == 0 or array[mid] < min_r:
                    break
                if min_r <= array[mid]:
                    count += 1
                    mid -= 1
                else:
                    break
            while True:
                if mid1 == len(array) or array[mid] > max_r:
                    break
                if max_r >= array[mid1]:
                    count += 1
                    mid1 += 1
                else:
                    break
            return count
        elif array[mid] < min_r:
            lo = mid + 1
        elif array[mid] > max_r:
            hi = mid - 1
