def reduce_base(k, base):
    if k in base:
        return 0, base
    grade = len(base)
    if grade == 1:
        if k < base[0]:
            return 1, [k, base[0]]
        else:
            return -1, [base[0], k]
    ilo = 0
    ihi = grade - 1
    if k < base[0]:
        return 1, [k] + base
    if k > base[ihi]:
        if grade % 2 == 0:
            return 1, base + [k]
        else:
            return -1, base + [k]
    imid = ihi + ilo
    if grade == 2:
        return -1, [base[0], k, base[1]]
    while True:
        if ihi - ilo == 1:
            break
        if base[imid] > k:
            ihi = imid
        else:
            ilo = imid
        imid = (ilo + ihi) // 2
    if ilo % 2 == 1:
        return 1, base[:ihi] + [k] + base[ihi:]
    else:
        return -1, base[:ihi] + [k] + base[ihi:]

